#!/usr/bin/env bash
# Applies the Zangetsu branding + build fixes to the windows/ runner.
#
# windows/ is generated by `flutter create --platforms=windows` in CI rather than
# committed, so anything that has to live inside it is patched in here, right
# after generation and before `flutter build windows`. Idempotent.
set -euo pipefail

APP_NAME="Zangetsu"
cd "$(dirname "$0")/.."

[ -d windows ] || { echo "windows/ missing — run flutter create first" >&2; exit 1; }

# 1. App icon (exe icon, taskbar, title bar).
cp windows_overrides/app_icon.ico windows/runner/resources/app_icon.ico
echo "icon: replaced windows/runner/resources/app_icon.ico"

# 2. Executable name: watch_app.exe -> Zangetsu.exe. flutter reads BINARY_NAME
#    from CMakeLists.txt to find the exe, so this is the only place to change.
sed -i "s/set(BINARY_NAME \"[^\"]*\")/set(BINARY_NAME \"${APP_NAME}\")/" windows/CMakeLists.txt

# 3. Name shown in task manager / file properties (version resource).
#    Only FileDescription, InternalName and OriginalFilename are changed.
#    CompanyName and ProductName are deliberately LEFT as generated: Flutter's
#    path_provider builds the app-data folder (%APPDATA%\<CompanyName>\<ProductName>)
#    from them, so changing them silently moves every user's settings, login and
#    installed sources to a new empty folder (this is what v0.2 did by mistake).
sed -i \
  -e "s|\(VALUE \"FileDescription\", \)\"[^\"]*\"|\1\"${APP_NAME}\"|" \
  -e "s|\(VALUE \"InternalName\", \)\"[^\"]*\"|\1\"${APP_NAME}\"|" \
  -e "s|\(VALUE \"OriginalFilename\", \)\"[^\"]*\"|\1\"${APP_NAME}.exe\"|" \
  windows/runner/Runner.rc

# 4. Initial window title (also set at runtime by DesktopWindow.init()).
sed -i "s/L\"watch_app\"/L\"${APP_NAME}\"/" windows/runner/main.cpp

# 5. permission_handler_windows includes <experimental/coroutine>, which recent
#    MSVC rejects (STL1011). Define it right after project() so it applies to
#    every plugin target.
if ! grep -q _SILENCE_EXPERIMENTAL_COROUTINE windows/CMakeLists.txt; then
  sed -i '/^project(/a add_compile_definitions(_SILENCE_EXPERIMENTAL_COROUTINE_DEPRECATION_WARNINGS)' windows/CMakeLists.txt
fi

echo "--- result ---"
grep -n "BINARY_NAME \"" windows/CMakeLists.txt | head -2
grep -n "_SILENCE_EXPERIMENTAL_COROUTINE" windows/CMakeLists.txt
grep -n "${APP_NAME}" windows/runner/Runner.rc windows/runner/main.cpp
